function matchesTrainingSlug(session:any, slug:string){const trainingSlug=session.training?.slug; if(trainingSlug===slug)return true; if(slug==='desp'&&['desp','desp-dssp','desp-initial','desp-vae'].includes(trainingSlug))return true; return false;}
