async function sessionsForSlug(slug:string){const rows=(await listSessions()).filter((session:any)=>isPublicUpcomingSession(session)&&matchesTrainingSlug(session,slug));return slug==='aps'&&!rows.length?apsFallbackSessions:rows;}

export default async function Page({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const f=formations.find(x=>x.slug.endsWith(slug));if(!f)notFound();const sessions=await sessionsForSlug(slug);if(slug==='aps')return <ApsPage f={f} sessions={sessions}/>;if(slug==='a3p-apr')return <A3pReferencePage sessions={sessions}/>;if(slug==='desp')return <DespChoicePage sessions={sessions}/>;if(slug==='ssiap-1')return <SsiapReferencePage sessions={sessions}/>;return <SecurityTrainingPage f={f} sessions={sessions} slug={slug}/>}

